import crypto from "node:crypto"
import fs from "node:fs"
import path from "node:path"
import {
  CODEX_HOME,
  loadState,
  log,
  saveState,
  sleep,
  withLock,
} from "./config.ts"
import type { NotionClient, PageResponse } from "./notion.ts"
import { redact } from "./redact.ts"

// Codex memories (features.memories) are generated by Codex itself, in the background:
// phase 1 extracts notes from each idle session, phase 2 consolidates them into
// $CODEX_HOME/memories/memory_summary.md and MEMORY.md. This module reads those files and
// mirrors them into the user's Notion Memories with Source = Codex.

export type MemoryType = "Profile" | "Preference" | "Work"

export interface CodexMemory {
  type: MemoryType
  title: string
  content: string
  from: string
}

export interface MemorySyncResult {
  total: number
  created: number
  updated: number
  removed: number
  skippedEdited: number
}

const POLL_MS = 5000

export function memoriesDir(): string {
  return path.join(CODEX_HOME, "memories")
}

export function parseCodexMemories(dir: string): CodexMemory[] {
  const out = [
    ...parseSummary(readIfExists(path.join(dir, "memory_summary.md"))),
    ...parseMemoryFile(readIfExists(path.join(dir, "MEMORY.md"))),
  ].filter((m) => !isPlaceholder(m.content))
  return dedupe(out).map((m) => ({
    ...m,
    title: redact(m.title),
    content: redact(m.content.replace(/\s*\[Task \d+\]/g, "")),
  }))
}

export async function syncMemories(
  client: NotionClient
): Promise<MemorySyncResult> {
  const memories = parseCodexMemories(memoriesDir())
  const result: MemorySyncResult = {
    total: memories.length,
    created: 0,
    updated: 0,
    removed: 0,
    skippedEdited: 0,
  }
  if (!memories.length) {
    log(
      "memories: none found in",
      memoriesDir(),
      "(is [features] memories = true set in Codex?)"
    )
    return result
  }
  const state = loadState()
  const live = new Set<string>()
  for (const memory of memories) {
    const key = sha1(`${memory.type}|${memory.title}`)
    const hash = sha1(memory.content)
    live.add(key)
    const prev = state.memories[key]
    if (prev?.hash === hash) continue
    if (prev?.pageId) {
      if (await editedInNotion(client, prev.pageId, prev.lastEditedTime)) {
        state.memories[key] = { ...prev, hash }
        saveState(state)
        result.skippedEdited++
        continue
      }
      await client.trashPage(prev.pageId)
      result.updated++
    } else {
      result.created++
    }
    const page = await createMemoryPage(client, memory)
    state.memories[key] = {
      hash,
      title: memory.title,
      type: memory.type,
      pageId: page?.id,
      lastEditedTime: page?.last_edited_time,
    }
    saveState(state)
  }
  for (const [key, prev] of Object.entries(state.memories)) {
    if (live.has(key)) continue
    if (
      prev.pageId &&
      !(await editedInNotion(client, prev.pageId, prev.lastEditedTime))
    ) {
      await client.trashPage(prev.pageId)
      result.removed++
    }
    delete state.memories[key]
  }
  saveState(state)
  log(`memories: ${JSON.stringify(result)}`)
  return result
}

// Codex has no hook for "memories updated", so a hook worker watches Codex's own job table
// and the memory files, and imports as soon as a consolidation run finishes.
export async function watchMemories(
  client: NotionClient,
  opts: { startWindowMs: number; maxMs: number }
): Promise<void> {
  const started = Date.now()
  let lastHash = memoryFilesHash()
  let sawRunning = false
  while (Date.now() - started < opts.maxMs) {
    await sleep(POLL_MS)
    const running = await memoryJobRunning()
    sawRunning ||= running
    const hash = memoryFilesHash()
    if (hash !== lastHash && !running) {
      log("memories: Codex updated its memory files, importing")
      await withLock(() => syncMemories(client))
      lastHash = hash
    }
    if (!running && (sawRunning || Date.now() - started > opts.startWindowMs))
      return
  }
}

function parseSummary(text: string): CodexMemory[] {
  const out: CodexMemory[] = []
  for (const section of sections(text, 2)) {
    if (/^user profile/i.test(section.title) && section.body.trim())
      out.push({
        type: "Profile",
        title: "Codex user profile",
        content: section.body.trim(),
        from: "memory_summary.md › User Profile",
      })
    if (/^user preferences/i.test(section.title))
      for (const b of bullets(section.body))
        out.push({
          type: "Preference",
          title: preferenceTitle(b),
          content: b,
          from: "memory_summary.md › User preferences",
        })
  }
  return out
}

function parseMemoryFile(text: string): CodexMemory[] {
  const out: CodexMemory[] = []
  for (const group of sections(text, 1)) {
    const subsections = sections(group.body, 2)
    const scope = group.body.match(/^scope:\s*(.+)$/m)?.[1]
    const appliesTo = group.body.match(/^applies_to:\s*(.+)$/m)?.[1]
    const knowledge = subsections.filter((s) =>
      /^(reusable knowledge|failures)/i.test(s.title)
    )
    const tasks = subsections
      .filter((s) => /^task \d+/i.test(s.title))
      .map((s) => s.title.replace(/^Task \d+:\s*/i, ""))
    if (knowledge.length || tasks.length) {
      const content = [
        scope && `Scope: ${scope}`,
        appliesTo && `Applies to: ${appliesTo}`,
        tasks.length && `Tasks:\n${tasks.map((t) => `- ${t}`).join("\n")}`,
        ...knowledge.map(
          (k) =>
            `${k.title}:\n${bullets(k.body)
              .map((b) => `- ${b}`)
              .join("\n")}`
        ),
      ]
        .filter(Boolean)
        .join("\n\n")
      out.push({
        type: "Work",
        title: titleFrom(group.title.replace(/^Task Group:\s*/i, "")),
        content,
        from: `MEMORY.md › ${group.title}`,
      })
    }
    for (const s of subsections.filter((s) =>
      /^user preferences/i.test(s.title)
    ))
      for (const b of bullets(s.body))
        out.push({
          type: "Preference",
          title: preferenceTitle(b),
          content: b,
          from: `MEMORY.md › ${group.title}`,
        })
  }
  return out
}

// The same preference often appears in both files with different wording around a quote.
function dedupe(memories: CodexMemory[]): CodexMemory[] {
  const seen: { type: MemoryType; key: string }[] = []
  return memories.filter((m) => {
    const key = normalizeKey(quoteOf(m.content) ?? m.content)
    if (
      seen.some(
        (s) => s.type === m.type && (s.key.includes(key) || key.includes(s.key))
      )
    )
      return false
    seen.push({ type: m.type, key })
    return true
  })
}

async function createMemoryPage(
  client: NotionClient,
  memory: CodexMemory
): Promise<PageResponse | undefined> {
  // `parent: "memory"` writes to the token owner's Notion Memories database.
  const res = await client.request<{ pages?: { id: string }[] }>(
    "POST",
    "/v1/tools/run",
    {
      type: "create_pages",
      create_pages: {
        parent: "memory",
        allow_async: false,
        pages: [
          {
            properties: {
              title: memory.title,
              Type: memory.type,
              Source: "Codex",
            },
            content: `${memory.content}\n\n(Imported from Codex memories: ${memory.from})`,
          },
        ],
      },
    }
  )
  const id = res.pages?.[0]?.id
  return id ? client.getPage(id) : undefined
}

async function editedInNotion(
  client: NotionClient,
  pageId: string,
  lastEditedTime: string | undefined
): Promise<boolean> {
  const page = await client.getPage(pageId).catch((e: Error) => {
    log("memories: could not read", pageId, e.message)
    return undefined
  })
  if (!page || page.in_trash) return false
  const edited = Boolean(
    lastEditedTime &&
      page.last_edited_time &&
      page.last_edited_time !== lastEditedTime
  )
  if (edited)
    log("memories: keeping", pageId, "because it was edited in Notion")
  return edited
}

async function memoryJobRunning(): Promise<boolean> {
  const db = path.join(CODEX_HOME, "memories_1.sqlite")
  if (!fs.existsSync(db)) return false
  try {
    const { DatabaseSync } = await import("node:sqlite")
    const conn = new DatabaseSync(db, { readOnly: true })
    try {
      return (
        conn
          .prepare("SELECT 1 FROM jobs WHERE status = 'running' LIMIT 1")
          .all().length > 0
      )
    } finally {
      conn.close()
    }
  } catch (e) {
    log(
      "memories: job table unavailable:",
      e instanceof Error ? e.message : String(e)
    )
    return false
  }
}

function memoryFilesHash(): string {
  return sha1(
    ["MEMORY.md", "memory_summary.md"]
      .map((f) => readIfExists(path.join(memoriesDir(), f)))
      .join("\0")
  )
}

function sections(
  text: string,
  level: number
): { title: string; body: string }[] {
  const heading = new RegExp(`^${"#".repeat(level)} (.+)$`, "gm")
  const out: { title: string; body: string }[] = []
  let prev: { title: string; end: number } | undefined
  for (const match of text.matchAll(heading)) {
    const index = match.index ?? 0
    if (prev) out.push({ title: prev.title, body: text.slice(prev.end, index) })
    prev = { title: match[1].trim(), end: index + match[0].length }
  }
  if (prev) out.push({ title: prev.title, body: text.slice(prev.end) })
  return out
}

function bullets(section: string): string[] {
  return section
    .split("\n")
    .filter((l) => /^\s*- /.test(l))
    .map((l) => l.replace(/^\s*- /, "").trim())
    .filter(Boolean)
}

// Codex seeds memory files with placeholder text such as "No preferences recorded yet."
function isPlaceholder(content: string): boolean {
  const text = content.trim()
  return text.length < 12 || /^(no|not)\b[^.]*\b(yet|recorded)\b/i.test(text)
}

function quoteOf(text: string): string | undefined {
  return text.match(/[“"]([^”"]{8,})[”"]/)?.[1]
}

// Prefer the user's own words when Codex quoted them; otherwise use the text before "->".
function preferenceTitle(bullet: string): string {
  const quote = quoteOf(bullet)
  return titleFrom(
    quote && quote.length >= 25 ? quote : bullet.split(/\s->\s/)[0]
  )
}

function titleFrom(text: string): string {
  const t = text
    .replace(/\s*\[Task \d+\]/g, "")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/^[“"]([^”"]+)[”"]\.?$/, "$1")
  const title = t.charAt(0).toUpperCase() + t.slice(1)
  return title.length > 90 ? `${title.slice(0, 87)}…` : title
}

function normalizeKey(text: string): string {
  return text
    .toLowerCase()
    .replace(/\[task \d+\]/g, "")
    .replace(/[^a-z0-9]/g, "")
}

function readIfExists(file: string): string {
  try {
    return fs.readFileSync(file, "utf8")
  } catch {
    return ""
  }
}

function sha1(text: string): string {
  return crypto.createHash("sha1").update(text).digest("hex")
}
